def _canon(o):
    """set 排序后序列化（与捕获口径一致）。"""
    if isinstance(o, dict):
        return {k: _canon(v) for k, v in o.items()}
    if isinstance(o, (list, tuple)):
        return [_canon(v) for v in o]
    if isinstance(o, (set, frozenset)):
        return sorted(_canon(v) for v in o)
    return o

def _pipeline(gans, zhis):
    """按 analyze_gongliang 编排序依次跑五阶段（与编排器同参同序）。"""
    day_gan = gans[2]
    inp = _prepare_inputs(None, day_gan, list(gans), list(zhis),
                          work_actions=None, work_types=None,
                          fei_shen=None, gong_shen=None,
                          zeishen_bushen_result=None)
    pos = _compute_position_sets(inp['day_wx'], gans, zhis,
                                 inp['wa_list'], inp['fei'],
                                 inp['gshen'], inp['tomb_works'])
    rules = _apply_gong_point_rules(
        inp['day_gan'], inp['day_wx'], gans, zhis,
        gshen=inp['gshen'], san_he_formed=inp['san_he_formed'],
        non_aux=pos['non_aux'], active_tomb_works=pos['active_tomb_works'],
        involved_positions=pos['involved_positions'],
        zhi_targets=pos['zhi_targets'], gan_cats=pos['gan_cats'],
        strong_positions=pos['strong_positions'],
        destructive_positions=pos['destructive_positions'],
        _zb_bao=inp['zb_bao'], _zb_clian=inp['zb_clian'],
        _zb_jing=inp['zb_jing'], all_work_actions=inp['wa_list'])
    caps = _apply_caps_and_direction(
        inp['day_gan'], inp['day_wx'], gans, zhis,
        inp['wa_list'], inp['wtypes'], inp['gshen'], inp['fei'],
        pos['control_action_count'],
        points=rules['points'], involved_cats=pos['involved_cats'],
        zhi_targets=pos['zhi_targets'], gan_cats=pos['gan_cats'],
        fei_cats=pos['fei_cats'], non_aux=pos['non_aux'],
        has_severe_harm=inp['has_severe_harm'],
        _fang_ju_formed=rules['_fang_ju_formed'],
        _zhiku_tombs=rules['_zhiku_tombs'], _zb_jing=inp['zb_jing'],
        _zb_bao_counted=rules['_zb_bao_counted'],
        _zb_pyramid=rules['_zb_pyramid'],
        yuanshen_hit=rules['yuanshen_hit'],
        hua_chengju=rules['hua_chengju'], reasons=rules['reasons'],
        san_he_formed=inp['san_he_formed'],
        _tg_huai_struct=rules['_tg_huai_struct'],
        _tg_huai_note=rules['_tg_huai_note'],
        _yuanshen_family_pts=rules['_yuanshen_family_pts'],
        evidence=rules['evidence'], annotations=rules['annotations'])
    built = _build_gongliang_result(
        day_wx=inp['day_wx'], zg=inp['zg'], gshen=inp['gshen'],
        fei=inp['fei'], non_aux=pos['non_aux'],
        points=caps['points'], reasons=caps['reasons'],
        level=caps['level'], raw_level=caps['raw_level'],
        zhi_jing=caps['zhi_jing'], penalty=caps['penalty'],
        involved_cats=pos['involved_cats'], gong_cats=pos['gong_cats'],
        chain_len=rules['chain_len'],
        yuanshen_hit=rules['yuanshen_hit'],
        _zb_bao_counted=rules['_zb_bao_counted'],
        _zb_boost=rules['_zb_boost'],
        zb_jing_adopted=caps['zb_jing_adopted'],
        yongshen_xiong=caps['yongshen_xiong'], fuhe=caps['fuhe'],
        _strength_gl=caps['_strength_gl'],
        _zb_bao=inp['zb_bao'], _zb_clian=inp['zb_clian'],
        _zb_jing=inp['zb_jing'],
        pocai_signal=caps['pocai_signal'],
        pocai_severity=caps['pocai_severity'],
        pocai_reason=caps['pocai_reason'],
        evidence=rules['evidence'], annotations=rules['annotations'])
    return inp, pos, rules, caps, built

