        inp, *_ = _pipeline(gans, zhis)
        pin = PIN[pan]['ph1']
        proj = {k: _canon(inp[k]) for k in ('wtypes', 'fei', 'gshen',
                'tomb_works', 'san_he_formed', 'has_severe_harm', 'zb',
                'zb_bao', 'zb_clian', 'zb_jing', 'day_gan', 'day_wx')}
        assert proj == {k: pin[k] for k in proj}
        assert len(inp['wa_list']) == pin['_wa_list_len']

