class TestEndToEnd:
    """端到端：analyze_gongliang 全量输出 == 拆分前实测。"""

    @pytest.mark.parametrize('pan', list(PANS))
    def test_analyze_gongliang_unchanged(self, pan):
        gans, zhis = PANS[pan]
        r = analyze_gongliang(day_gan=gans[2], gans=list(gans), zhis=list(zhis))
        assert _canon(r) == BOOK_A[pan]

    @pytest.mark.parametrize('pan', list(PILLARS_PIN))
    def test_analyze_gongliang_pillars_signature(self, pan):
        gans, zhis = PANS[pan]
        p = Pillars(gans[0], zhis[0], gans[1], zhis[1],
                    gans[2], zhis[2], gans[3], zhis[3])
        r = analyze_gongliang(p)
        assert _canon(r) == PILLARS_PIN[pan]

